queries.legs:
PREFIX fcd: <https://example.org/fincrime-data#>
SELECT ?txid ?ts ?from ?to ?amountLog WHERE {
  VALUES ?txid { 2131053 2204314 2282865 }
  ?tx a fcd:Transaction ;
      fcd:txId ?txid ;
      fcd:timestamp ?ts ;
      fcd:fromAccount ?from ;
      fcd:toAccount ?to ;
      fcd:amountLog ?amountLog .
}

