queries.context:
PREFIX fcd: <https://example.org/fincrime-data#>
SELECT DISTINCT ?account ?customerType ?industry ?tenure ?pep ?risk
WHERE {
  VALUES ?txid { 2131053 2204314 2282865 }
  ?tx a fcd:Transaction ;
      fcd:txId ?txid ;
      (fcd:fromAccount ?account .)
    UNION
    (fcd:toAccount ?account .)
  ?account fcd:customerType ?customerType .
  OPTIONAL { ?account fcd:industry ?industry }
  ?account fcd:onboardingTenureDays ?tenure .
  ?account fcd:pepFlag ?pep .
  ?account fcd:riskRating ?risk .
}

